"""Original finite explanatory states for the LOGIC chapters."""
def make(identifier, chapter, marker, title, intro, nodes, edges, rows, assumptions):
    keys = [node[0] for node in nodes]
    steps = []
    for name, why, actor, focus, active, values, field in rows:
        label, before, after, cause = field
        assert len(values) == len(keys)
        steps.append(dict(title=name, explanation=why, actor=actor, focus=focus,
                          active=active, states=dict(zip(keys, values)),
                          fields=[dict(name=label, before=before, after=after, why=cause)],
                          bands=[dict(label=label, value=after, detail=cause)]))
    return dict(id=identifier, volume='computer-architecture', chapter=chapter,
                anchor=chapter, insert_before=marker, title=title, intro=intro,
                assumptions=assumptions + ' Шаги — конечные состояния объяснения; цвет дублирован текстом, все шаги доступны для печати.',
                nodes=[dict(id=k, label=label, sub=sub) for k,label,sub in nodes],
                edges=[dict(id=k, **{'from':a,'to':b}, label=label) for k,a,b,label in edges], steps=steps)

